mapper.select:
SELECT shot_id, take_id, source_in_ms, source_out_ms, created_at, updated_at
FROM selected_takes
WHERE shot_id = #{shotId}

mapper.update:
UPDATE selected_takes
SET take_id = #{takeId},
    source_in_ms = #{sourceInMs},
    source_out_ms = #{sourceOutMs},
    updated_at = #{updatedAt}
WHERE shot_id = #{shotId}
